const entries = $input.all().flatMap(item => {
  const data = item.json;
  if (Array.isArray(data)) return data;
  if (Array.isArray(data.items)) return data.items;
  if (Array.isArray(data.data)) return data.data;
  return [data];
});

const reportQueryFiles = entries.filter(entry =>
  entry &&
  entry.type === 'file' &&
  typeof entry.path === 'string' &&
  entry.path.includes('reports/') &&
  entry.path.endsWith('.txt')
);

return reportQueryFiles.map(file => ({
  json: {
    report_query_path: file.path
  }
}));

const source = $input.first().json;
const base64Content = source.content;
const text = Buffer.from(base64Content, 'base64').toString('utf-8');
const lines = String(text).split('\n');
const result = { report_query_path: source.path };

for (const line of lines) {
  const match = line.match(/-\s*(.+?):\s*(.+)/);
  if (match) {
    const key = match[1].trim().toLowerCase().replace(/\s+/g, '_');
    result[key] = match[2].trim();
  }
}

return [{ json: result }];

const merged = {};
for (const item of $input.all()) Object.assign(merged, item.json);
return [{ json: merged }];

