parameters.jsCode:
/**
 * Resilient parser for Agent 1 output.
 * Works even when JSON is truncated near the end.
 * Strategy:
 * 1) Try normal JSON parse.
 * 2) If it fails, recover complete rule objects from the broken "rules" array.
 */

const items = $input.all();

function stripCodeFences(text) {
  return String(text || "")
    .trim()
    .replace(/^```(?:json)?\s*/i, "")
    .replace(/\s*```$/i, "")
    .trim();
}

function normalizeSeverity(v) {
  const s = String(v || "").toUpperCase();
  return s === "CRITICAL" || s === "HIGH" || s === "MEDIUM" ? s : "MEDIUM";
}

function normalizeEvidenceType(v) {
  const s = String(v || "").toLowerCase();
  return s === "running_config" || s === "show_command" || s === "external_only"
    ? s
    : "external_only";
}

function normalizeRule(rule, index) {
  const r = rule && typeof rule === "object" ? rule : {};
  return {
    id: String(r.id || `R${String(index + 1).padStart(3, "0")}`),
    domain: String(r.domain || "Other"),
    title: String(r.title || "Unnamed rule"),
    severity: normalizeSeverity(r.severity),
    evidence_type: normalizeEvidenceType(r.evidence_type),
    ios_command: String(r.ios_command || ""),
    expected_pattern: String(r.expected_pattern || ""),
    rationale: String(r.rationale || "")
  };
}

function parseJsonSafe(text) {
  try {
    return { value: JSON.parse(text), error: null };
  } catch (err1) {
    // Try largest object slice
    const first = text.indexOf("{");
    const last = text.lastIndexOf("}");
    if (first !== -1 && last !== -1 && last > first) {
      const slice = text.slice(first, last + 1);
      try {
        return { value: JSON.parse(slice), error: null };
      } catch (err2) {
        return { value: null, error: String(err2.message || err2) };
      }
    }
    return { value: null, error: String(err1.message || err1) };
  }
}

function extractStringField(text, field) {
  const re = new RegExp(`"${field}"\\s*:\\s*"([^"]*)"`);
  const m = text.match(re);
  return m ? m[1] : null;
}

function extractNumberField(text, field) {
  const re = new RegExp(`"${field}"\\s*:\\s*(\\d+)`);
  const m = text.match(re);
  return m ? Number(m[1]) : null;
}

function extractStringArrayField(text, field) {
  // Best effort for complete arrays only
  const startRe = new RegExp(`"${field}"\\s*:\\s*\\[`);
  const startMatch = startRe.exec(text);
  if (!startMatch) return null;

  const start = startMatch.index + startMatch[0].length - 1; // index of [
  let i = start;
  let depth = 0;
  let inStr = false;
  let esc = false;

  for (; i < text.length; i++) {
    const ch = text[i];
    if (inStr) {
      if (esc) {
        esc = false;
      } else if (ch === "\\\\") {
        esc = true;
      } else if (ch === "\"") {
        inStr = false;
      }
      continue;
    }
    if (ch === "\"") {
      inStr = true;
      continue;
    }
    if (ch === "[") depth++;
    if (ch === "]") {
      depth--;
      if (depth === 0) {
        const arrText = text.slice(start, i + 1);
        try {
          const parsed = JSON.parse(arrText);
          return Array.isArray(parsed) ? parsed.map(String) : null;
        } catch {
          return null;
        }
      }
    }
  }
  return null;
}

function recoverRulesFromBrokenJson(text) {
  const rulesKey = /"rules"\s*:\s*\[/.exec(text);
  if (!rulesKey) return [];

  // Position at first char after the opening bracket of "rules"
  let i = rulesKey.index + rulesKey[0].length;
  const objects = [];
  let cur = "";
  let objDepth = 0;
  let inStr = false;
  let esc = false;

  for (; i < text.length; i++) {
    const ch = text[i];

    if (inStr) {
      cur += ch;
      if (esc) {
        esc = false;
      } else if (ch === "\\\\") {
        esc = true;
      } else if (ch === "\"") {
        inStr = false;
      }
      continue;
    }

    if (ch === "\"") {
      if (objDepth > 0) cur += ch;
      inStr = true;
      continue;
    }

    if (objDepth === 0) {
      if (ch === "{") {
        objDepth = 1;
        cur = "{";
      } else if (ch === "]") {
        break; // end of rules array
      } else {
        // skip commas/whitespace between objects
      }
      continue;
    }

    // objDepth > 0
    cur += ch;
    if (ch === "{") objDepth++;
    if (ch === "}") {
      objDepth--;
      if (objDepth === 0) {
        objects.push(cur);
        cur = "";
      }
    }
  }

  const parsedRules = [];
  for (const objText of objects) {
    try {
      parsedRules.push(JSON.parse(objText));
    } catch {
      // ignore malformed object fragments
    }
  }

  return parsedRules;
}

return items.map((item) => {
  const raw = String(item.json.output || "");
  const cleaned = stripCodeFences(raw);

  // First try full parse
  const parsedFull = parseJsonSafe(cleaned);

  let source_type = "unknown";
  let source_metadata = {};
  let domains = [];
  let rules = [];
  let parse_error = null;

  if (parsedFull.value && typeof parsedFull.value === "object") {
    const p = parsedFull.value;
    source_type = String(p.source_type || "unknown");
    source_metadata = p.source_metadata && typeof p.source_metadata === "object" ? p.source_metadata : {};
    domains = Array.isArray(p.domains) ? p.domains.map(String) : [];
    rules = Array.isArray(p.rules) ? p.rules : (p.rules && typeof p.rules === "object" ? [p.rules] : []);
  } else {
    // Recovery path for truncated JSON
    parse_error = parsedFull.error || "Invalid JSON";
    source_type = extractStringField(cleaned, "source_type") || "unknown";

    const url = extractStringField(cleaned, "url");
    const retrieved_at_utc = extractStringField(cleaned, "retrieved_at_utc");
    const sections_used = extractStringArrayField(cleaned, "sections_used");
    source_metadata = {
      ...(url ? { url } : {}),
      ...(retrieved_at_utc ? { retrieved_at_utc } : {}),
      ...(Array.isArray(sections_used) ? { sections_used } : {})
    };

    rules = recoverRulesFromBrokenJson(cleaned);
    domains = Array.from(new Set(rules.map((r) => String((r && r.domain) || "Other"))));

    // If domains field exists and parsed, prefer union
    const declaredDomains = extractStringArrayField(cleaned, "domains");
    if (Array.isArray(declaredDomains)) {
      domains = Array.from(new Set([...domains, ...declaredDomains.map(String)]));
    }
  }

  const normalizedRules = rules
    .map((r, idx) => normalizeRule(r, idx))
    .filter((r) => r.title.trim().length > 0);

  return {
    json: {
      ...(parse_error ? { rules_parse_error: parse_error } : {}),
      rules_source_type: source_type,
      rules_source_metadata: source_metadata,
      rules_domains: domains.length ? domains : Array.from(new Set(normalizedRules.map((r) => r.domain))),
      rules_count: normalizedRules.length,
      rules: normalizedRules
    }
  };
});

const merged = {};
for (const item of $input.all()) Object.assign(merged, item.json);
if (!merged.devices) merged.devices = 'R1';
merged.rules_json = JSON.stringify(merged.rules || []);
return [{ json: merged }];

