return $input.all().map(item => ({
  json: {
    report_url: item.json.content.html_url,
    report_tag: item.json.commit.message
  }
}));

const merged = {};
for (const item of $input.all()) Object.assign(merged, item.json);
return [{ json: merged }];

const items = $input.all();

return items.map(item => {
  let outputText = String(item.json.output || '').trim();
  outputText = outputText.replace(/```json\n?/gi, '').replace(/```/g, '').trim();

  try {
    const parsedJson = JSON.parse(outputText);
    return { json: parsedJson };
  } catch {
    return { json: { create_issue: false } };
  }
});

